package com.personal.assistant.module.automation.service;import com.personal.assistant.common.exception.*;import com.personal.assistant.module.automation.entity.AutomationExecution;import com.personal.assistant.module.automation.mapper.AutomationExecutionMapper;import org.springframework.stereotype.Service;@Service public class AutomationRetryService{private final AutomationExecutionMapper executions;private final AutomationService automation;public AutomationRetryService(AutomationExecutionMapper executions,AutomationService automation){this.executions=executions;this.automation=automation;}public void retry(Long uid,Long id){AutomationExecution x=executions.selectById(id);if(x==null||!uid.equals(x.getUserId())||!"FAILED".equals(x.getStatus()))throw new BusinessException(ErrorCode.NOT_FOUND,"失败执行记录不存在");automation.runNow(uid,x.getRuleId());}}
